"use strict";
const images = [{"title":"Горные вершины","src":"data:image/svg+xml;base64,"},{"title":"Лесное озеро","src":"data:image/jpeg;base64,"},{"title":"Дорога через лес","src":"data:image/jpeg;base64,"},{"title":"Пустынные дюны","src":"data:image/jpeg;base64,"},{"title":"Водопад в лесу","src":"data:image/jpeg;base64,"},{"title":"Морское побережье","src":"data:image/jpeg;base64,"},{"title":"Зелёный лес","src":"data:image/jpeg;base64,"},{"title":"Озеро среди гор","src":"data:image/jpeg;base64,"}];

const gallery = document.querySelector(".gallery");
const viewport = document.querySelector(".gallery__viewport");
const track = document.querySelector(".gallery__track");
const previousButton = document.querySelector(".arrow--prev");
const nextButton = document.querySelector(".arrow--next");
const pager = document.querySelector(".pager");
const status = document.querySelector(".status");
let currentPage = 0;
let perPage = readPerPage();
let touchStart = null;

function readPerPage() {
  return Number(getComputedStyle(gallery).getPropertyValue("--per-page").trim());
}

images.forEach((image, index) => {
  const slide = document.createElement("figure");
  slide.className = "slide";
  slide.setAttribute("role", "group");
  slide.setAttribute("aria-roledescription", "слайд");
  slide.setAttribute("aria-label", `${index + 1} из ${images.length}`);
  const img = document.createElement("img");
  img.src = image.src;
  img.alt = image.title;
  img.width = 900;
  img.height = 700;
  img.draggable = false;
  const caption = document.createElement("figcaption");
  const number = document.createElement("span");
  number.className = "slide__number";
  number.textContent = `${String(index + 1).padStart(2, "0")} / ${String(images.length).padStart(2, "0")}`;
  caption.append(number, document.createTextNode(image.title));
  slide.append(img, caption);
  track.append(slide);
});

function pageCount() {
  return Math.ceil(images.length / perPage);
}

function buildPager() {
  pager.replaceChildren();
  for (let page = 0; page < pageCount(); page++) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "pager__dot";
    button.setAttribute("aria-label", `Перейти на страницу ${page + 1}`);
    button.setAttribute("aria-controls", "gallery-track");
    button.addEventListener("click", () => goToPage(page));
    pager.append(button);
  }
}

function render() {
  const firstIndex = currentPage * perPage;
  const firstSlide = track.children[0];
  const gap = parseFloat(getComputedStyle(track).columnGap) || 0;
  const offset = firstIndex * (firstSlide.getBoundingClientRect().width + gap);
  track.style.transform = `translateX(-${offset}px)`;
  previousButton.disabled = currentPage === 0;
  nextButton.disabled = currentPage === pageCount() - 1;
  [...pager.children].forEach((button, index) => {
    if (index === currentPage) button.setAttribute("aria-current", "page");
    else button.removeAttribute("aria-current");
  });
  [...track.children].forEach((slide, index) => {
    slide.setAttribute("aria-hidden", String(index < firstIndex || index >= firstIndex + perPage));
  });
  const lastIndex = Math.min(firstIndex + perPage, images.length);
  const imageRange = perPage === 1 ? `${firstIndex + 1}` : `${firstIndex + 1}–${lastIndex}`;
  status.textContent = `Страница ${currentPage + 1} из ${pageCount()} · Фото ${imageRange} из ${images.length}`;
}
function goToPage(page) {
  currentPage = Math.max(0, Math.min(page, pageCount() - 1));
  render();
}
previousButton.addEventListener("click", () => goToPage(currentPage - 1));
nextButton.addEventListener("click", () => goToPage(currentPage + 1));
gallery.addEventListener("keydown", (event) => {
  let targetPage;
  if (event.key === "ArrowLeft") targetPage = currentPage - 1;
  else if (event.key === "ArrowRight") targetPage = currentPage + 1;
  else if (event.key === "Home") targetPage = 0;
  else if (event.key === "End") targetPage = pageCount() - 1;
  else return;
  event.preventDefault();
  goToPage(targetPage);
});
viewport.addEventListener("touchstart", (event) => {
  touchStart = event.touches.length === 1
    ? { x: event.touches[0].clientX, y: event.touches[0].clientY }
    : null;
}, { passive: true });
viewport.addEventListener("touchend", (event) => {
  if (!touchStart || !event.changedTouches.length) return;
  const dx = event.changedTouches[0].clientX - touchStart.x;
  const dy = event.changedTouches[0].clientY - touchStart.y;
  if (Math.abs(dx) > 45 && Math.abs(dx) > Math.abs(dy)) {
    goToPage(currentPage + (dx < 0 ? 1 : -1));
  }
  touchStart = null;
}, { passive: true });
viewport.addEventListener("touchcancel", () => { touchStart = null; }, { passive: true });

let resizeFrame;
function handleResize() {
  cancelAnimationFrame(resizeFrame);
  resizeFrame = requestAnimationFrame(() => {
    const firstVisibleIndex = currentPage * perPage;
    const nextPerPage = readPerPage();
    if (nextPerPage !== perPage) {
      perPage = nextPerPage;
      currentPage = Math.min(Math.floor(firstVisibleIndex / perPage), pageCount() - 1);
      buildPager();
    }
    track.classList.add("is-resizing");
    render();
    void track.offsetWidth;
    track.classList.remove("is-resizing");
  });
}
if ("ResizeObserver" in window) {
  new ResizeObserver(handleResize).observe(viewport);
} else {
  window.addEventListener("resize", handleResize);
}

buildPager();
render();
